SET @ga_author := COALESCE((SELECT um.user_id FROM `pws_usermeta` um WHERE um.meta_key = 'pws_capabilities' AND um.meta_value LIKE '%"administrator"%' ORDER BY um.user_id LIMIT 1), 1);
