-- 1) Create the post only if it does not exist yet
INSERT INTO `pws_posts` (post_author, post_date, post_date_gmt, post_content, post_title, post_excerpt, post_status, comment_status, ping_status, post_password, post_name, to_ping, pinged, post_modified, post_modified_gmt, post_content_filtered, post_parent, guid, menu_order, post_type, post_mime_type, comment_count)
SELECT @ga_author, NOW(), UTC_TIMESTAMP(), '', 'CubeIT – Magnetic Cube Computer for Schools', '', 'publish', 'closed', 'closed', '', 'cubeit', '', '', NOW(), UTC_TIMESTAMP(), '', 0, '', @ga_order, 'ga_project', '', 0
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `pws_posts` WHERE post_type = 'ga_project' AND post_name = 'cubeit');

SET @ga_pid := (SELECT ID FROM `pws_posts` WHERE post_type = 'ga_project' AND post_name = 'cubeit' ORDER BY ID LIMIT 1);

-- 2) English source text (always refreshed)
UPDATE `pws_posts` SET
  post_title   = 'CubeIT – Magnetic Cube Computer for Schools',
  post_excerpt = 'An open-hardware learning computer for Swiss schools (2015): every component – processor, power, display, USB, sound – sits in its own magnetic cube. Children snap the cubes together, the computer boots, and they learn how a computer really works.',
  post_content = '<!-- wp:paragraph -->\n<p>CubeIT turned the black box “computer” into building blocks that children can hold in their hands. Each function sat in its own 50 mm cube with magnetic faces: a C.H.I.P. board as the brain, a power cube, an HDMI/DVI display cube, a USB cube and a sound cube. When the right cubes touch, the computer boots – input, processing and output become something children can see and feel.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class="wp-block-heading">What we built in 2015</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class="wp-block-list">\n<!-- wp:list-item -->\n<li>Cube concept and magnetic CubeBus connector (5 V, GND, I2C, mirror-symmetric pinout)</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>First C.H.I.P. board order and 3D-printed prototype shells</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>First learning games in Python and pygame, running directly on the board</li>\n<!-- /wp:list-item -->\n<!-- wp:list-item -->\n<li>Tools for cube identification (I2C EEPROM), GPIO tests and classroom provisioning</li>\n<!-- /wp:list-item -->\n</ul>\n<!-- /wp:list -->\n\n<!-- wp:heading -->\n<h2 class="wp-block-heading">Why it stopped</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>The technology worked – market access did not. Compulsory schooling in Switzerland is a cantonal matter (Art. 62 Federal Constitution), so there is no single federal customer. Product conformity (toy safety, EMC, radio, batteries), a pilot evaluated by a university of teacher education, cantonal teaching-material approval and public procurement would have required an estimated CHF 30–80k and 2–4 years before the first sale – out of reach for an early-stage team.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class="wp-block-heading">Open source today</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Concept, hardware architecture, Lehrplan 21 mapping, the Swiss regulatory roadmap, the tools and a free micro learning game (“Build your computer”, three missions in DE/FR/IT/EN) are published on GitHub under MIT and CC BY-SA – free for every school.</p>\n<!-- /wp:paragraph -->',
  post_status  = 'publish',
  post_modified = NOW(), post_modified_gmt = UTC_TIMESTAMP(),
  guid = CONCAT('https://giannialagna.me/?post_type=ga_project&p=', @ga_pid)
WHERE ID = @ga_pid;

-- 3) Portfolio fields + translations (replace managed keys only)
DELETE FROM `pws_postmeta` WHERE post_id = @ga_pid AND meta_key IN ('_ga_category', '_ga_status', '_ga_year', '_ga_start', '_ga_role', '_ga_url', '_ga_repo', '_ga_log_hide', '_ga_stack', '_ga_facts', '_ga_featured', '_ga_i18n');
INSERT INTO `pws_postmeta` (post_id, meta_key, meta_value) VALUES
  (@ga_pid, '_ga_category', 'EdTech · Hardware Engineering'),
  (@ga_pid, '_ga_status', 'discontinued'),
  (@ga_pid, '_ga_year', '2015'),
  (@ga_pid, '_ga_start', '2015'),
  (@ga_pid, '_ga_role', 'Co-Founder · Concept & Development'),
  (@ga_pid, '_ga_url', ''),
  (@ga_pid, '_ga_repo', 'https://github.com/GianniAlagna/CubeIT'),
  (@ga_pid, '_ga_log_hide', ''),
  (@ga_pid, '_ga_stack', 'C.H.I.P., Debian, Python, pygame, I2C, KiCad, 3D printing'),
  (@ga_pid, '_ga_facts', 'Year|2015\nBrain|C.H.I.P. (USD 9)\nCurriculum|Lehrplan 21 · MI\nLicense|MIT · CC BY-SA'),
  (@ga_pid, '_ga_featured', ''),
  (@ga_pid, '_ga_i18n', 'a:5:{s:2:"de";a:6:{s:5:"title";s:53:"CubeIT – Magnetischer Würfel-Computer für Schulen";s:7:"excerpt";s:280:"Ein Open-Hardware-Lerncomputer für Schweizer Schulen (2015): Jede Komponente – Prozessor, Strom, Bildschirm, USB, Ton – steckt in einem eigenen Magnetwürfel. Kinder fügen die Würfel zusammen, der Computer startet, und sie verstehen, wie ein Computer wirklich funktioniert.";s:7:"content";s:1669:"<p>CubeIT machte aus der Blackbox «Computer» Bausteine, die Kinder in die Hand nehmen können. Jede Funktion sass in einem eigenen 50-mm-Würfel mit magnetischen Seiten: ein C.H.I.P.-Board als Gehirn, ein Strom-Würfel, ein HDMI/DVI-Bildschirm-Würfel, ein USB-Würfel und ein Ton-Würfel. Berühren sich die richtigen Würfel, startet der Computer – Eingabe, Verarbeitung und Ausgabe werden sicht- und greifbar.</p>\n<h2>Was wir 2015 gebaut haben</h2>\n<ul><li>Würfelkonzept und magnetischer CubeBus-Stecker (5 V, GND, I2C, spiegelsymmetrische Belegung)</li><li>Erste C.H.I.P.-Board-Bestellung und 3D-gedruckte Prototyp-Gehäuse</li><li>Erste Lernspiele in Python und pygame, direkt auf dem Board</li><li>Werkzeuge für Würfel-Erkennung (I2C-EEPROM), GPIO-Tests und die Einrichtung von Klassencomputern</li></ul>\n<h2>Warum wir gestoppt haben</h2>\n<p>Die Technik funktionierte – der Marktzugang nicht. Die Volksschule ist in der Schweiz Sache der Kantone (Art. 62 BV); einen einzelnen Bundeskunden gibt es nicht. Produktkonformität (Spielzeugsicherheit, EMV, Funk, Batterien), ein von einer Pädagogischen Hochschule evaluierter Pilot, die kantonale Lehrmittelzulassung und das öffentliche Beschaffungswesen hätten vor dem ersten Verkauf geschätzt CHF 30–80k und 2–4 Jahre erfordert – für ein Team in der Frühphase nicht machbar.</p>\n<h2>Heute Open Source</h2>\n<p>Konzept, Hardware-Architektur, Lehrplan-21-Zuordnung, die Schweizer Regulierungs-Roadmap, die Werkzeuge und ein kostenloses Micro-Learning-Spiel («Bau deinen Computer», drei Missionen in DE/FR/IT/EN) sind auf GitHub unter MIT und CC BY-SA veröffentlicht – frei für jede Schule.</p>";s:8:"category";s:30:"EdTech · Hardware Engineering";s:5:"facts";s:83:"Jahr|2015\nGehirn|C.H.I.P. (USD 9)\nLehrplan|Lehrplan 21 · MI\nLizenz|MIT · CC BY-SA";s:4:"role";s:36:"Mitgründer · Konzept & Entwicklung";}s:2:"it";a:6:{s:5:"title";s:50:"CubeIT – Computer a cubi magnetici per le scuole";s:7:"excerpt";s:270:"Un computer didattico open hardware per le scuole svizzere (2015): ogni componente – processore, alimentazione, schermo, USB, audio – si trova in un proprio cubo magnetico. I bambini uniscono i cubi, il computer si avvia e imparano come funziona davvero un computer.";s:7:"content";s:1710:"<p>CubeIT ha trasformato la scatola nera «computer» in mattoncini che i bambini possono tenere in mano. Ogni funzione era in un cubo di 50 mm con facce magnetiche: una scheda C.H.I.P. come cervello, un cubo di alimentazione, un cubo schermo HDMI/DVI, un cubo USB e un cubo audio. Quando i cubi giusti si toccano, il computer si avvia – input, elaborazione e output diventano visibili e tangibili.</p>\n<h2>Cosa abbiamo costruito nel 2015</h2>\n<ul><li>Concetto dei cubi e connettore magnetico CubeBus (5 V, GND, I2C, piedinatura simmetrica a specchio)</li><li>Primo ordine di schede C.H.I.P. e involucri prototipo stampati in 3D</li><li>Primi giochi didattici in Python e pygame, direttamente sulla scheda</li><li>Strumenti per l''identificazione dei cubi (EEPROM I2C), test GPIO e configurazione dei computer di classe</li></ul>\n<h2>Perché ci siamo fermati</h2>\n<p>La tecnologia funzionava – l''accesso al mercato no. In Svizzera la scuola dell''obbligo è di competenza cantonale (art. 62 Cost.), quindi non esiste un unico cliente federale. Conformità del prodotto (sicurezza dei giocattoli, CEM, radio, batterie), un progetto pilota valutato da un''alta scuola pedagogica, l''approvazione cantonale dei mezzi didattici e gli appalti pubblici avrebbero richiesto circa CHF 30–80k e 2–4 anni prima della prima vendita – fuori portata per un team in fase iniziale.</p>\n<h2>Oggi open source</h2>\n<p>Concetto, architettura hardware, corrispondenza con il Lehrplan 21, la roadmap normativa svizzera, gli strumenti e un gioco di micro-apprendimento gratuito («Costruisci il tuo computer», tre missioni in DE/FR/IT/EN) sono pubblicati su GitHub con licenza MIT e CC BY-SA – gratuiti per ogni scuola.</p>";s:8:"category";s:30:"EdTech · Hardware Engineering";s:5:"facts";s:93:"Anno|2015\nCervello|C.H.I.P. (USD 9)\nPiano di studio|Lehrplan 21 · MI\nLicenza|MIT · CC BY-SA";s:4:"role";s:35:"Co-fondatore · Concetto e sviluppo";}s:2:"fr";a:6:{s:5:"title";s:60:"CubeIT – Ordinateur à cubes magnétiques pour les écoles";s:7:"excerpt";s:305:"Un ordinateur pédagogique open hardware pour les écoles suisses (2015) : chaque composant – processeur, alimentation, écran, USB, son – se trouve dans son propre cube magnétique. Les enfants assemblent les cubes, l''ordinateur démarre, et ils comprennent comment fonctionne vraiment un ordinateur.";s:7:"content";s:1765:"<p>CubeIT a transformé la boîte noire « ordinateur » en blocs que les enfants peuvent tenir en main. Chaque fonction se trouvait dans un cube de 50 mm aux faces magnétiques : une carte C.H.I.P. comme cerveau, un cube d''alimentation, un cube écran HDMI/DVI, un cube USB et un cube son. Quand les bons cubes se touchent, l''ordinateur démarre – entrée, traitement et sortie deviennent visibles et tangibles.</p>\n<h2>Ce que nous avons construit en 2015</h2>\n<ul><li>Concept des cubes et connecteur magnétique CubeBus (5 V, GND, I2C, brochage symétrique en miroir)</li><li>Première commande de cartes C.H.I.P. et boîtiers prototypes imprimés en 3D</li><li>Premiers jeux éducatifs en Python et pygame, directement sur la carte</li><li>Outils d''identification des cubes (EEPROM I2C), tests GPIO et préparation des ordinateurs de classe</li></ul>\n<h2>Pourquoi nous avons arrêté</h2>\n<p>La technique fonctionnait – l''accès au marché, non. En Suisse, l''école obligatoire relève des cantons (art. 62 Cst.) : il n''existe pas de client fédéral unique. La conformité du produit (sécurité des jouets, CEM, radio, batteries), un projet pilote évalué par une haute école pédagogique, l''agrément cantonal des moyens d''enseignement et les marchés publics auraient exigé environ CHF 30–80k et 2–4 ans avant la première vente – hors de portée pour une équipe en phase de démarrage.</p>\n<h2>Aujourd''hui en open source</h2>\n<p>Concept, architecture matérielle, correspondance avec le Lehrplan 21, feuille de route réglementaire suisse, outils et un jeu de micro-apprentissage gratuit (« Construis ton ordinateur », trois missions en DE/FR/IT/EN) sont publiés sur GitHub sous licences MIT et CC BY-SA – gratuits pour chaque école.</p>";s:8:"category";s:30:"EdTech · Hardware Engineering";s:5:"facts";s:93:"Année|2015\nCerveau|C.H.I.P. (USD 9)\nPlan d''études|Lehrplan 21 · MI\nLicence|MIT · CC BY-SA";s:4:"role";s:40:"Cofondateur · Concept et développement";}s:2:"es";a:6:{s:5:"title";s:55:"CubeIT – Ordenador de cubos magnéticos para escuelas";s:7:"excerpt";s:282:"Un ordenador educativo de hardware abierto para las escuelas suizas (2015): cada componente – procesador, alimentación, pantalla, USB, sonido – está en su propio cubo magnético. Los niños unen los cubos, el ordenador arranca y aprenden cómo funciona realmente un ordenador.";s:7:"content";s:1780:"<p>CubeIT convirtió la caja negra «ordenador» en bloques que los niños pueden tener en la mano. Cada función estaba en un cubo de 50 mm con caras magnéticas: una placa C.H.I.P. como cerebro, un cubo de alimentación, un cubo de pantalla HDMI/DVI, un cubo USB y un cubo de sonido. Cuando los cubos correctos se tocan, el ordenador arranca: entrada, procesamiento y salida se vuelven visibles y tangibles.</p>\n<h2>Lo que construimos en 2015</h2>\n<ul><li>Concepto de cubos y conector magnético CubeBus (5 V, GND, I2C, asignación de pines simétrica en espejo)</li><li>Primer pedido de placas C.H.I.P. y carcasas prototipo impresas en 3D</li><li>Primeros juegos educativos en Python y pygame, directamente en la placa</li><li>Herramientas para identificar cubos (EEPROM I2C), pruebas GPIO y preparación de ordenadores de aula</li></ul>\n<h2>Por qué lo detuvimos</h2>\n<p>La tecnología funcionaba; el acceso al mercado, no. En Suiza la escuela obligatoria es competencia de los cantones (art. 62 de la Constitución Federal), por lo que no existe un único cliente federal. La conformidad del producto (seguridad de juguetes, CEM, radio, baterías), un piloto evaluado por una universidad de formación docente, la aprobación cantonal de material didáctico y la contratación pública habrían requerido unos CHF 30–80k y 2–4 años antes de la primera venta: fuera del alcance de un equipo en fase inicial.</p>\n<h2>Hoy en código abierto</h2>\n<p>El concepto, la arquitectura de hardware, la correspondencia con el Lehrplan 21, la hoja de ruta regulatoria suiza, las herramientas y un juego de microaprendizaje gratuito («Construye tu ordenador», tres misiones en DE/FR/IT/EN) están publicados en GitHub con licencias MIT y CC BY-SA: gratis para cualquier escuela.</p>";s:8:"category";s:33:"EdTech · Ingeniería de hardware";s:5:"facts";s:94:"Año|2015\nCerebro|C.H.I.P. (USD 9)\nPlan de estudios|Lehrplan 21 · MI\nLicencia|MIT · CC BY-SA";s:4:"role";s:35:"Cofundador · Concepto y desarrollo";}s:2:"la";a:6:{s:5:"title";s:47:"CubeIT – Computatrum cubis magneticis scholis";s:7:"excerpt";s:245:"Computatrum discendi apertum scholis Helveticis (MMXV): quaeque pars – processor, vis electrica, monitorium, USB, sonus – in suo cubo magnetico inest. Pueri cubos coniungunt, computatrum incipit, et discunt quomodo computatrum vere operetur.";s:7:"content";s:1686:"<p>CubeIT arcam obscuram «computatrum» in lapides aedificandi mutavit, quos pueri manibus tenere possunt. Quodque munus in suo cubo quinquaginta millimetrorum lateribus magneticis inerat: tabula C.H.I.P. ut cerebrum, cubus vis electricae, cubus monitorii HDMI/DVI, cubus USB et cubus soni. Cum cubi recti se tangunt, computatrum incipit – ingressus, tractatio et egressus visibiles et tangibiles fiunt.</p>\n<h2>Quid anno MMXV aedificavimus</h2>\n<ul><li>Consilium cuborum et nexus magneticus CubeBus (5 V, GND, I2C, dispositio speculariter symmetrica)</li><li>Prima tabularum C.H.I.P. emptio et involucra exemplaria typis tridimensionalibus facta</li><li>Primi ludi discendi Python et pygame scripti, in ipsa tabula currentes</li><li>Instrumenta ad cubos agnoscendos (EEPROM I2C), probationes GPIO et computatra classium paranda</li></ul>\n<h2>Cur destitimus</h2>\n<p>Ars technica operabatur – aditus ad forum non. In Helvetia schola publica res pagorum est (art. 62 Constitutionis Foederalis); emptor foederalis unus non exstat. Conformitas producti (securitas ludibriorum, EMC, radiophonia, pilae electricae), experimentum ab universitate paedagogica aestimatum, approbatio pagana instrumentorum docendi et emptiones publicae ante primam venditionem circiter CHF 30–80 milia et duos ad quattuor annos postulavissent – parvae turmae incipienti impossibile.</p>\n<h2>Hodie fons apertus</h2>\n<p>Consilium, architectura machinalis, concordantia cum Lehrplan 21, via regulatoria Helvetica, instrumenta et ludus brevis discendi gratuitus («Aedifica computatrum tuum», tres missiones DE/FR/IT/EN) in GitHub sub licentiis MIT et CC BY-SA publicata sunt – omnibus scholis libera.</p>";s:8:"category";s:24:"EdTech · Ars machinalis";s:5:"facts";s:94:"Annus|MMXV\nCerebrum|C.H.I.P. (USD 9)\nOrdo studiorum|Lehrplan 21 · MI\nLicentia|MIT · CC BY-SA";s:4:"role";s:40:"Conditor socius · Consilium et evolutio";}}');

COMMIT;

